function toInt(v){ const n = Number(v); return Number.isFinite(n) ? Math.floor(n) : null; }
function nonEmpty(v){ return v!==undefined && v!==null && String(v).trim()!=='' && String(v).toLowerCase()!=='undefined' && String(v).toLowerCase()!=='null'; }
const pickNE = (...vals)=> vals.find(nonEmpty);
const clamp = (n,lo,hi)=> Math.max(lo, Math.min(hi, n));
const HEX_OK = /^[a-f0-9]{12,64}$/i;
const STRICT_RE = /(?:^|\/)characters\/([a-f0-9]{12,64})(?:\/|$)/i;
const LOOSE_RE1 = /characters[_\-]([a-f0-9]{12,64})[_\-]/i;
const LOOSE_RE2 = /characters[_\-]([a-f0-9]{12,64})[_\-]pose\d{1,3}/i;
function extractHashFromString(s){
  if (!nonEmpty(s)) return null;
  const str=String(s);
  let m=str.match(STRICT_RE); if (m) return m[1];
  m=str.match(LOOSE_RE2)||str.match(LOOSE_RE1);
  return m?m[1]:null;
}
function sanitizePath(p){ return String(p||'').replace(/\/{2,}/g,'/').replace(/^\/+/,''); }
function isoNow(){ return new Date().toISOString(); }
function ensureIso(v){ try{ const d=new Date(v); if (!Number.isNaN(d.getTime())) return d.toISOString(); }catch{} return isoNow(); }
function joinUrl(base, key) {
  if (!base || !key) return null;
  return `${String(base).replace(/\/$/, '')}/${String(key).replace(/^\/+/, '')}`;
}
// NEW: extract poseNN from any string
function extractPoseFromString(s){
  if (!nonEmpty(s)) return null;
  const m = String(s).match(/pose[_-]?(\d{1,3})/i);
  return m ? toInt(m[1]) : null;
}

// Scan a node across runs for all items (newest→older)
function itemsAllRuns(nodeName, MAX_SCAN=40){
  const out=[], seen=new Set();
  try{
    const latest = $items(nodeName);
    if (Array.isArray(latest)) for (const it of latest){
      const sig = it?.json?.__uuid || JSON.stringify(Object.keys(it?.binary||{}));
      if (!seen.has(sig)){ seen.add(sig); out.push({ run:'latest', item: it }); }
    }
  }catch{}
  try{
    const last = $items(nodeName,0);
    if (Array.isArray(last)) for (const it of last){
      const sig = it?.json?.__uuid || JSON.stringify(Object.keys(it?.binary||{}));
      if (!seen.has(sig)){ seen.add(sig); out.push({ run:'last', item: it }); }
    }
  }catch{}
  for (let r=MAX_SCAN; r>=0; r--){
    try{
      const arr = $items(nodeName,0,r);
      if (!Array.isArray(arr) || !arr.length) continue;
      for (const it of arr){
        const sig = JSON.stringify([r,it?.json?.__uuid,Object.keys(it?.binary||{})]);
        if (!seen.has(sig)){ seen.add(sig); out.push({ run:r, item: it }); }
      }
    }catch{}
  }
  return out;
}

