const percentComplete = totalPoses > 0 
  ? Math.round((approvedCount / totalPoses) * 100) 
  : 0;
const readyForBook = approvedCount === totalPoses && totalPoses > 0;
const needsHumanReview = needsReviewCount > 0;

const manifest = {
  schema: 'lhb.run-manifest@v2.0',
  runStamp,
  characterHash: characterHash || 'unknown',
  orderId: perBookId,
  rootOrderId: rootOrderId || null,
  amazonOrderId: amazonOrderId || null,
  order: {
    orderId: perBookId,
    rootOrderId: rootOrderId || null,
    amazonOrderId: amazonOrderId || null,
    oneManifestUrl: oneManifestUrl || null,
    childName: childName,
    characterSpecs: characterSpecs,
    bookSpecs: bookSpecs,
    orderDetails: orderDetails,
    publicR2Url,
    r2BucketName: 'little-hero-assets'
  },
  poses: {
    total: totalPoses,
    approved: approvedCount,
    exhausted: exhaustedCount,
    retried: retriedCount,
    failed: Math.max(totalPoses - approvedCount - exhaustedCount, 0),
    needingReview: needsReviewCount
  },
  entries,
  reviewQueue,
  summary: {
    percentComplete,
    readyForBook,
    needsHumanReview
  },
  workflow: {
    currentStage: '2A-complete',
    nextWorkflow: needsHumanReview ? '2B-retry' : '2B',  // Changed from 'book-generation' to '2B'
    requiresHumanReview: needsHumanReview
  },
  generatedAt: isoNow(),
  _debug: {
    poseIndexFixes // non-breaking: useful to audit mis-stamped inputs
  }
};

/* ---------------- Generate manifest key — per-item only for sibling orders ---------------- */
let manifestKey = sanitizePath(`book-mvp-simple-adventure/orders/${perBookId}/manifests/2a-manifest.json`);
const manifestUrl = `${backendUrl}/api/manifests/${manifestKey}`;
manifest.manifestUrl = manifestUrl;
manifest.originalManifestUrl = manifestUrl;
manifest.orderId = perBookId;
manifest.rootOrderId = rootOrderId || null;
manifest.amazonOrderId = amazonOrderId || null;
manifest.order.orderId = perBookId;
manifest.order.rootOrderId = rootOrderId || null;
manifest.order.amazonOrderId = amazonOrderId || null;
manifest.order.oneManifestUrl = oneManifestUrl || null;
console.log(`✓ Using per-item manifest path: ${manifestKey}`);

/* ---------------- Prepare binary output ---------------- */
const manifestJson = JSON.stringify(manifest, null, 2);
const binaryOut = {
  data: {
    data: Buffer.from(manifestJson,'utf-8').toString('base64'),
    mimeType: 'application/json',
    fileName: '2a-manifest.json',
    fileExtension: 'json'
  }
};

console.log({
  node: 'Write Run Manifest v2.0.6',
  runId: runId || '(none)',
  bucket: 'little-hero-orders',
  manifestKey,
  characterHash: manifest.characterHash,
  poses: manifest.poses,
  summary: manifest.summary,
  workflow: manifest.workflow,
  orderContext: {
    orderId: manifest.order.orderId || '(none)',
    rootOrderId: manifest.order.rootOrderId || '(none)',
    amazonOrderId: manifest.order.amazonOrderId || '(none)',
    oneManifestUrl: manifest.order.oneManifestUrl || '(none)',
    childName: manifest.order.childName || '(none)'
  },
  poseIndexFixes
});

/* ---------------- Clean up storage ---------------- */
if ($execution.customData?.poseResults){
  if (runId && runId !== 'merged' && $execution.customData.poseResults[runId]){
    delete $execution.customData.poseResults[runId];
    console.log('Cleaned up accumulator storage for runId:', runId);
  } else if (runId === 'merged'){
    $execution.customData.poseResults = {};
    console.log('Cleaned up all accumulator storage (merged mode)');
  }
}

// ========== CLEANUP: Delete global amazonOrderId ==========
if (global.currentAmazonOrderId) {
  console.log('🧹 Clearing global amazonOrderId:', global.currentAmazonOrderId);
  delete global.currentAmazonOrderId;
}
// ==========================================================

return [{
  json: { 
    manifestKey,
    manifest, 
    characterHash: manifest.characterHash,
    orderId: perBookId,
    rootOrderId: rootOrderId || null,
    amazonOrderId: amazonOrderId || null,
    oneManifestUrl: oneManifestUrl || null,
    manifestUrl: manifest.manifestUrl,
    manifestReady: true,
    uploadBucket: 'little-hero-orders'
  },
  binary: binaryOut
}];
